// Posters and validation are generated by default; pass --video to also export MP4.
// node render-api-scenes.mjs /path/to/tmath-skills/assets/wasm [--preview] [--relations-only | --composition-only | --method-only]
// CPU tmath Lua animation -> H.264 MP4 and poster. No scene rebuilding per frame.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url));
const bundle=path.resolve(process.argv[2]);
const preview=process.argv.includes('--preview');
const output=path.resolve(dir,'../IMAGE/07-SW-Overview');
const temp=path.join(dir,'temp/api-scenes');
await fs.mkdir(temp,{recursive:true});await fs.mkdir(output,{recursive:true});
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));
const r=await createTMath('return tmath.scene {width=1600,height=860}', 'bootstrap.lua',{
  renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm')),
});
r.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
try {
for (const name of (process.argv.includes('--method-only')?['render-method']:process.argv.includes('--relations-only')?['api-relations']:process.argv.includes('--composition-only')?['scene-composition']:['api-relations','scene-composition','render-method'])) {
const filename=`sw-overview-${name}.lua`;
const source=await fs.readFile(path.join(dir,filename),'utf8');
const alone=new Set([...source.matchAll(/^-- @standalone: (.*)$/gm)].flatMap(m=>m[1].split(/\s+/)));
const owned=new Map([...source.matchAll(/^-- @contain: (.*)$/gm)].flatMap(m=>m[1].split(/\s+/)).map(s=>{
  const [id,target]=s.split('='),[panel,inset]=target.split(':');return [id,{panel,inset:Number(inset)}];
}));
const right=b=>b.x+b.width,bottom=b=>b.y+b.height;
const clearance=(a,b)=>Math.min(a.x-b.x,a.y-b.y,right(b)-right(a),bottom(b)-bottom(a));
 r.loadLua(source,filename);
 const duration=r.duration,[width,height]=r.size(),fps=30;
 const frames=Math.ceil(duration*fps)+1;
 const issues=new Set(),seen=new Set();let minCanvas=Infinity,minPanel=Infinity;
 for(let frame=0;frame<frames;frame++) {
  const time=Math.min(frame/fps,duration),report=r.layoutReport(time,4);
  const byId=new Map(report.objects.map(o=>[o.id,o]));
  const texts=report.objects.filter(o=>o.type==='text'&&o.visible);
  for(const t of texts) {
    seen.add(t.id);const b=t.paintBounds;
    if(!b||b.width<=0||b.height<=0){issues.add(`null bounds: ${t.id}`);continue;}
    const c=clearance(b,{x:0,y:0,width,height});minCanvas=Math.min(c,minCanvas);
    if(c<4)issues.add(`canvas: ${t.id}`);
    if(owned.has(t.id)){
      const {panel,inset}=owned.get(t.id),bb=byId.get(panel)?.paintBounds;
      if(!bb){issues.add(`missing panel: ${panel}`);continue;}
      const n=clearance(b,bb);minPanel=Math.min(n,minPanel);
      if(n<inset)issues.add(`containment: ${t.id}: ${n.toFixed(2)}`);
    }else if(!alone.has(t.id))issues.add(`missing ledger: ${t.id}`);
  }
  if(name==='render-method') {
    const packets=report.objects.filter(o=>o.visible&&/^packet_(sw|gl|wg)_(circle|square)$/.test(o.id));
    for(const token of packets)for(const t of texts) {
      const a=token.paintBounds,b=t.paintBounds;
      if(a&&b&&Math.max(b.x-right(a),a.x-right(b))<4&&Math.max(b.y-bottom(a),a.y-bottom(b))<4)issues.add(`payload crosses label: ${token.id}/${t.id}`);
    }
  }
  for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++){
   const a=texts[i].paintBounds,b=texts[j].paintBounds;if(!a||!b)continue;
   if(Math.max(b.x-right(a),a.x-right(b))<4&&Math.max(b.y-bottom(a),a.y-bottom(b))<4)issues.add(`text gap: ${texts[i].id} / ${texts[j].id}`);
  }

 }
 for(const id of [...alone,...owned.keys()])if(!seen.has(id))issues.add(`unused ledger: ${id}`);
 const summary={duration,width,height,fps,frames,texts:seen.size,minCanvas,minPanel,issues:[...issues]};
 console.log(JSON.stringify(summary));
 await fs.writeFile(path.join(temp,`${name}-audit.json`),JSON.stringify(summary,null,2));
 if(issues.size)throw Error('Animation audit failed');
 const raw={width,height,channels:4};
 const samples=name==='api-relations'?[0,3,6.9,10,13,duration]:name==='scene-composition'?[0,2.85,4.9,6.95,7.6,9,9.7,duration]:[0,2.8,4.8,7.6,9.3,11.9,14.1,16.2,18.2,20.1,duration];
 for(const time of samples.filter(t=>t<=duration)) {
    await sharp(Buffer.from(r.render(time,true)),{raw}).png().toFile(path.join(temp,`${name}-${time.toFixed(2)}.png`));
 }
 // Check the represented state, not just that an encoder succeeds.
 if(name==='scene-composition') {
   const report=r.layoutReport(duration,4), byId=new Map(report.objects.map(o=>[o.id,o]));
   for(const id of ['direct_source_circle_paint','direct_source_square_paint','direct_source_triangle_paint','group_source_circle_paint','group_source_square_paint','group_source_triangle_paint','offscreen_triangle_paint','offscreen_square_paint','direct_circle_paint','direct_triangle_paint','direct_square_paint','group_circle_paint','composited_image'])
     if(!byId.get(id)?.visible)throw Error(`Lost persistent object: ${id}`);
   const pixels=Buffer.from(r.render(duration,true));
   for(const [x,y,color] of [[1830,590,[233,165,59]],[1830,1590,[137,143,139]],[1250,1590,[233,165,59]],[1740,1570,[40,120,219]],[1830,1500,[192,169,221]],[1250,1500,[130,84,188]]]) {
     const got=[...pixels.subarray((y*width+x)*4,(y*width+x)*4+3)];
     if(got.some((v,i)=>Math.abs(v-color[i])>2))throw Error(`Group composition pixel ${x},${y}: ${got}`);
   }
   const direct=Buffer.from(r.render(7.6,true));
   const directAt=(590*width+1830)*4;
   if([233,165,59].some((v,i)=>Math.abs(direct[directAt+i]-v)>2))throw Error('Direct draw z-order');
   if(!r.layoutReport(7.6,4).objects.some(o=>o.id==='offscreen_square_paint'&&o.visible))throw Error('Offscreen and direct results must be visible together');
   // An opacity edit affects the composed bitmap, never the opaque scratch result.
   r.loadLua(source.replace('local groupOpacity=128','local groupOpacity=96'),'opacity-variant.lua');
   const variant=Buffer.from(r.render(r.duration,true));
   const at=(1590*width+1830)*4;
   const expected=[113,137,159];
   if(expected.some((v,i)=>Math.abs(variant[at+i]-v)>2))throw Error(`Group opacity variant: ${[...variant.subarray(at,at+3)]}`);
   const scratch=(1590*width+1250)*4;
   if([233,165,59].some((v,i)=>Math.abs(variant[scratch+i]-v)>2))throw Error('Group opacity leaked into offscreen children');
   r.loadLua(source,filename);
   const original=r.bounds('direct_source_square_paint',duration);
   r.loadLua(source.replace('w=135,h=115','w=157,h=115'),'geometry-variant.lua');
   const delta=r.bounds('direct_source_square_paint',r.duration).width-original.width;
   if(Math.abs(delta-9.9)>0.05)throw Error(`Retained shape width variant: ${delta}`);
   const widened=Buffer.from(r.render(r.duration,true));
   for(const [x,y,color] of [[1940,590,[233,165,59]],[1360,1590,[233,165,59]],[1940,1590,[244,210,157]]]) {
     const at=(y*width+x)*4;
     if(color.some((v,i)=>Math.abs(widened[at+i]-v)>2))throw Error('Geometry change did not reach offscreen/composite pixels');
   }
 } else if(name==='render-method') {
   // Equal rank, three independent sources, equivalent illustrative output geometry.
   const pixels=Buffer.from(r.render(duration,true));
   const crops=await Promise.all([450,1200,1950].map(x=>sharp(pixels,{raw}).extract({left:x-100,top:1190,width:200,height:180}).raw().toBuffer()));
   for(let j=1;j<crops.length;j++){let max=0,at=0;for(let i=0;i<crops[0].length;i++){const d=Math.abs(crops[0][i]-crops[j][i]);if(d>max){max=d;at=i;}}if(max>4)throw Error(`Output geometry comparison: ${max}`);console.log(JSON.stringify({lane:j,maxEdgeDifference:max}));}
   for(const layer of ['renderer','platform']) {
     const ys=['sw','gl','wg'].map(id=>r.bounds(`${layer}_${id}_box`,duration).y);
     if(Math.max(...ys)-Math.min(...ys)>0.01)throw Error('Backend row misaligned');
   }
   const original=['sw','gl','wg'].map(id=>r.bounds(`output_${id}_square`,duration));
   r.loadLua(source.replace('w=58,h=52','w=76,h=52'),'shape-variant.lua');
   ['sw','gl','wg'].forEach((id,i)=>{
     const delta=r.bounds(`output_${id}_square`,r.duration).width-original[i].width;
     if(Math.abs(delta-18)>0.02)throw Error('Backend output dependency');
   });
 } else {
   for(const siblings of [['SwCanvas','GlCanvas','WgCanvas'],['SwRenderer','GlRenderer','WgRenderer'],['Picture','Text','ChildShape','ChildScene'],['LinearGradient','RadialGradient']]) {
     const boxes=siblings.map(name=>r.bounds(`box_${name}`,duration));
     const centers=boxes.map(b=>b.x+b.width/2);
     if(Math.max(...boxes.map(b=>b.width))-Math.min(...boxes.map(b=>b.width))>0.01)throw Error(`Unequal sibling width: ${siblings}`);
     if(Math.max(...centers)-Math.min(...centers)>0.01)throw Error(`Unequal sibling rank: ${siblings}`);
   }
   for(const pair of [['Canvas','CanvasImpl'],['CanvasImpl','RenderMethod'],['Scene','Paint'],['Shape','RenderShape']]) {
     const centers=pair.map(id=>{const b=r.bounds(`box_${id}`,duration);return b.y+b.height/2;});
     if(Math.abs(centers[0]-centers[1])>0.01)throw Error(`Main reference is not horizontal: ${pair}`);
   }
   const original=r.bounds('paint_matrix_shaft',duration);
   r.loadLua(source.replace('Matrix={1190','Matrix={1220'),'variant.lua');
   const delta=r.bounds('paint_matrix_shaft',r.duration).width-original.width;
   if(Math.abs(delta-30)>.05)throw Error(`Class route dependency: ${delta}`);
 }
 r.loadLua(source,filename);
 const poster=Buffer.from(r.render(duration,true));
 await sharp(poster,{raw}).webp({lossless:true}).toFile(path.join(output,`${name}.webp`));
 if(name==='render-method') await sharp(poster,{raw}).png().toFile(path.join(output,`${name}.png`));
 if (!preview && process.argv.includes('--video')) {
  const encoder=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba',
    '-video_size',`${width}x${height}`,'-framerate',String(fps),'-i','pipe:0','-an','-c:v','libx264','-preset','medium',
    '-crf','19','-pix_fmt','yuv420p','-movflags','+faststart',path.join(output,`${name}.mp4`)],{stdio:['pipe','inherit','inherit']});
  const completed=once(encoder,'close');
  for(let frame=0;frame<frames;frame++){
    if(!encoder.stdin.write(Buffer.from(r.render(Math.min(frame/fps,duration),true))))await once(encoder.stdin,'drain');
    if(frame%180===0)console.log(`encoding: ${frame}/${frames}`);
  }
  encoder.stdin.end();const[code]=await completed;if(code!==0)throw Error(`ffmpeg: ${code}`);
 }
 console.log(`PASS: ${name}; full-frame text audit and model variant verified.`);
}
} finally { r.destroy(); }
